-- public.jewel_gain(it item, p_skill text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.jewel_gain(it item, p_skill text)
 RETURNS double precision
 LANGUAGE plpgsql
 STABLE
AS $function$
#variable_conflict use_column
begin
  return (

  select coalesce(count(*), 0)
       * (jewel_bonus() * mark_of(it.mark, 'bright') + coalesce((it.mark->>'cut')::double precision, 0) * least(100, it.ql) / 100)
       * case when it.def = 'circlet' then circlet_share() else 1 end
    from unnest(stones_of(it)) s join gem_def g on lower(g.name) = s
   where g.skill = p_skill
  );
end
$function$
